-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.build_render_manifest(p_page_version_id uuid)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.build_render_manifest(p_page_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE owner_site uuid;
BEGIN
  SELECT site_id INTO owner_site FROM public.page_versions WHERE id = p_page_version_id;
  IF owner_site IS NULL THEN RAISE EXCEPTION 'no such page version' USING ERRCODE = 'CMS03'; END IF;
  -- This function runs as its owner, so RLS is not filtering for it. The check
  -- has to be here, not left to whoever called.
  IF NOT app.has_page_access((SELECT page_id FROM public.page_versions WHERE id=p_page_version_id)) THEN
    RAISE EXCEPTION 'not permitted to read this page version' USING ERRCODE = 'CMS02';
  END IF;
  RETURN app.build_render_manifest_internal(p_page_version_id);
END
$function$
